<?php
declare(strict_types=1);
ini_set('session.cookie_httponly','1');ini_set('session.cookie_samesite','Lax');if(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')ini_set('session.cookie_secure','1');
session_start();date_default_timezone_set('Asia/Tehran');
header('Cache-Control: no-store, private, max-age=0');header('Pragma: no-cache');header('X-Robots-Tag: noindex, nofollow');
if(!file_exists(__DIR__.'/config.php')){header('Location:install.php');exit;}$c=require __DIR__.'/config.php';
try{$pdo=new PDO('mysql:host='.$c['db_host'].';dbname='.$c['db_name'].';charset=utf8mb4',$c['db_user'],$c['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);require_once __DIR__.'/schema.php';ensure_product_schema($pdo);require_once __DIR__.'/payment_lib.php';}catch(Throwable $e){exit('اتصال برقرار نیست.');}
function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}function toman($n){return number_format((int)$n).' تومان';}
function find_order_by_token(PDO $pdo,string $token): ?array {$st=$pdo->prepare('SELECT o.*,c.name customer_name,c.phone,c.address FROM orders o JOIN customers c ON c.id=o.customer_id WHERE o.public_token=? LIMIT 1');$st->execute([$token]);$r=$st->fetch();return $r?:null;}
function ensure_token_for_order(PDO $pdo,int $id): string {$st=$pdo->prepare('SELECT public_token FROM orders WHERE id=?');$st->execute([$id]);$t=trim((string)$st->fetchColumn());if($t===''){$t=bin2hex(random_bytes(24));$pdo->prepare('UPDATE orders SET public_token=? WHERE id=?')->execute([$t,$id]);}return $t;}
$error='';$order=null;$items=[];$token=trim((string)($_GET['t']??''));
if($_SERVER['REQUEST_METHOD']==='POST'){
    $orderId=max(0,(int)($_POST['order']??0));$phone=preg_replace('/\D+/','',(string)($_POST['phone']??''))??'';
    if($orderId<1||!preg_match('/^09\d{9}$/',$phone))$error='شماره سفارش و موبایل را درست وارد کنید.';
    else{$st=$pdo->prepare('SELECT o.id FROM orders o JOIN customers c ON c.id=o.customer_id WHERE o.id=? AND c.phone=? LIMIT 1');$st->execute([$orderId,$phone]);$id=(int)($st->fetchColumn()?:0);if(!$id)$error='سفارشی با این اطلاعات پیدا نشد.';else{$token=ensure_token_for_order($pdo,$id);$_SESSION['last_order_id']=$id;$_SESSION['last_phone']=$phone;header('Location:track.php?t='.rawurlencode($token),true,303);exit;}}
}
if($token!==''&&preg_match('/^[a-f0-9]{32,64}$/',$token))$order=find_order_by_token($pdo,$token);
if(!$order&&!empty($_SESSION['last_order_id'])&&!empty($_SESSION['last_phone'])&&$token===''){
    $id=(int)$_SESSION['last_order_id'];$phone=(string)$_SESSION['last_phone'];$st=$pdo->prepare('SELECT o.id FROM orders o JOIN customers c ON c.id=o.customer_id WHERE o.id=? AND c.phone=? LIMIT 1');$st->execute([$id,$phone]);if($st->fetchColumn()){$token=ensure_token_for_order($pdo,$id);header('Location:track.php?t='.rawurlencode($token),true,303);exit;}
}
if($token!==''&&!$order)$error='لینک پیگیری معتبر نیست یا سفارش پیدا نشد.';
if($order){$q=$pdo->prepare('SELECT oi.*,p.image_path FROM order_items oi LEFT JOIN products p ON p.id=oi.product_id WHERE oi.order_id=? ORDER BY oi.id');$q->execute([(int)$order['id']]);$items=$q->fetchAll();}
$payCfg=ts_payment_config($pdo);$onlinePay=!empty($payCfg['enabled'])&&trim((string)$payCfg['merchant'])!=='';
$labels=['new'=>'ثبت شد','confirmed'=>'تأیید شد','preparing'=>'در حال جمع‌آوری','ready'=>'آماده ارسال','out'=>'در مسیر','delivered'=>'تحویل شد'];$flow=array_keys($labels);$current=$order?array_search($order['status'],$flow,true):false;
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#11823b"><meta name="robots" content="noindex,nofollow"><title>پیگیری سفارش | سوپرمارکت طهران</title><link rel="stylesheet" href="assets/style.css?v=20261024-track-pay"><style>.track-wrap{max-width:720px;margin:24px auto;padding:0 15px}.track-card{background:#fff;border:1px solid #e7eee8;border-radius:18px;padding:16px;margin-bottom:14px}.timeline{display:grid;grid-template-columns:repeat(6,1fr);gap:6px;margin:18px 0}.step{font-size:10px;text-align:center;color:#859087}.step i{display:block;width:24px;height:24px;border-radius:50%;margin:0 auto 6px;background:#e8eee9}.step.done{color:#11823b;font-weight:700}.step.done i{background:#11823b}.track-item{display:flex;align-items:center;gap:10px;padding:10px 0;border-bottom:1px solid #eef1ee}.track-item img{width:56px;height:56px;object-fit:contain;border-radius:10px}.track-item .grow{flex:1}.lookup{display:grid;grid-template-columns:1fr 1fr auto;gap:8px}.securehint{font-size:12px;color:#647268;background:#f4f8f5;padding:9px 11px;border-radius:10px;margin-top:10px}.paybox{background:#f2f8f4;border:1px solid #dbeadf;border-radius:13px;padding:12px;margin:12px 0}.paid{background:#e7f7eb;color:#17602e}@media(max-width:650px){.timeline{grid-template-columns:repeat(3,1fr);row-gap:14px}.lookup{grid-template-columns:1fr}.track-wrap{margin-top:12px}}</style></head><body><header class="top"><a class="brand" href="index.php"><span class="logo">📦</span><span><b>پیگیری سفارش</b><small>سوپرمارکت طهران</small></span></a><a class="btn pale" href="index.php">ادامه خرید</a></header><main class="track-wrap"><?php if(!$order):?><div class="track-card"><h2>سفارشت کجاست؟</h2><form class="lookup" method="post" autocomplete="off"><input name="order" inputmode="numeric" placeholder="شماره سفارش" required><input name="phone" inputmode="numeric" autocomplete="tel" placeholder="شماره موبایل" required><button class="btn">پیگیری امن</button></form><div class="securehint">شماره موبایل داخل آدرس صفحه ذخیره نمی‌شود. بعد از تأیید، یک لینک امن مخصوص همان سفارش ساخته می‌شود.</div><?php if($error):?><div class="notice"><?=e($error)?></div><?php endif;?></div><?php else:?><div class="track-card"><div class="sectionhead"><div><h2>سفارش #<?=(int)$order['id']?></h2><p><?=e($order['created_at'])?></p></div><b><?=toman($order['total'])?></b></div><?php if($order['status']==='cancelled'):?><div class="notice">این سفارش لغو شده و موجودی کالاها به فروشگاه برگشته است.</div><?php else:?><div class="timeline"><?php foreach($labels as $k=>$v):$ix=array_search($k,$flow,true);?><div class="step <?=($current!==false&&$ix<=$current)?'done':''?>"><i></i><?=e($v)?></div><?php endforeach;?></div><?php endif;?><?php if(($order['payment_status']??'')==='paid'):?><div class="paybox paid">✅ پرداخت آنلاین تأیید شده<?php if(!empty($order['payment_ref_id'])):?> · کد پیگیری <?=e($order['payment_ref_id'])?><?php endif;?></div><?php elseif($onlinePay&&$order['status']!=='cancelled'):?><div class="paybox"><b>💳 پرداخت آنلاین</b><p class="muted">اگر می‌خواهی این سفارش را آنلاین پرداخت کنی، از همین لینک امن استفاده کن.</p><a class="btn wide" href="payment_start.php?t=<?=e($token)?>">پرداخت <?=toman($order['total'])?></a></div><?php else:?><p><b>پرداخت:</b> در محل</p><?php endif;?><?php if(!empty($order['discount_total'])):?><p><b>تخفیف:</b> <?=toman($order['discount_total'])?><?=!empty($order['coupon_code'])?' · کد '.e($order['coupon_code']):''?></p><?php endif;?><p><b>تحویل:</b> <?=e($order['delivery_slot'])?></p><?php if(!empty($order['delivery_zone_name'])):?><p><b>محدوده:</b> <?=e($order['delivery_zone_name'])?><?php if(!empty($order['delivery_eta'])):?> · <?=e($order['delivery_eta'])?><?php endif;?></p><?php endif;?><p><b>آدرس:</b> <?=e($order['address'])?></p><?php if($order['delivery_lat']!==null&&$order['delivery_lng']!==null):?><p><a class="btn pale" target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&amp;query=<?=rawurlencode((string)$order['delivery_lat'].','.(string)$order['delivery_lng'])?>">📍 مشاهده لوکیشن ثبت‌شده</a></p><?php endif;?></div><div class="track-card"><h3>کالاهای سفارش</h3><a class="btn wide" style="margin-bottom:12px" href="reorder.php?t=<?=e($token)?>">🔁 همین خرید را دوباره انجام بده</a><?php foreach($items as $it):?><div class="track-item"><?php if(!empty($it['image_path'])):?><img src="<?=e($it['image_path'])?>" alt=""><?php endif;?><div class="grow"><b><?=e($it['product_name'])?></b><?php if(!empty($it['adjustment_note'])):?><div class="muted"><?=e($it['adjustment_note'])?></div><?php endif;?><div class="muted"><?=number_format((int)$it['quantity'])?> عدد · <?=toman((int)$it['unit_price'])?></div></div><strong><?=toman((int)$it['unit_price']*(int)$it['quantity'])?></strong></div><?php endforeach;?></div><?php endif;?></main><script>try{sessionStorage.removeItem('tehran_delivery_location_v1');}catch(e){}</script></body></html>
